// The browser suite by browser (row 7.10.2), as last run: every test that failed in some browser, with its cause there (SUITE_CAUSES) or
// 'pass' (`fixed`: what made it pass since, shown by a rerun; `since`: a change made since that the run's machine has not rerun). A test not listed passed in every browser that ran. Recorded by hand
// from the runs' JSON reports and logs.
export const SUITE_CAUSES = Object.freeze({
  stale: 'the spec predates a change in Play and fails in every browser',
  race: 'the spec reads a state before worker mode delivers it, or before a loaded host has drawn it',
  harness: 'Playwright\'s synthetic input or headless window is not a real browser\'s, and the spec cannot pass as written',
  spec: 'the spec assumes what that browser does not do (a Chromium switch, a whole-pixel layout, a readback outside the frame that drew)',
  platform: 'the spec\'s case has no path in that browser on that system',
  api: 'the spec needs a Chromium-only API',
  play: 'a Play bug in that browser or simulation mode',
  unexplained: 'it fails and its cause is not found',
});
export const SUITE_RUN = {
  date: '2026-11-11', machine: 'the Mac (Apple M2 Pro, macOS on Darwin 25.6, a quiet host: [Mac pass](mac-pass-2026-11-11.md#1-the-suite-711-713-7102)), headless, on 881d4cbc\'s code', tests: 53,
  rerun: 'One project at a time, one worker, Firefox muted through a wrapper of the repository\'s config. Both Chromium failures ran again alone and in probes, failing each time with the suite\'s default headless Chromium, which draws with SwiftShader on the Mac (15 to 18 fps), and each passed once with the same spec on Metal. The four skips in each (load-game.spec:61 and save-folder.spec\'s three) need `.work/real-saves`, the Linux host\'s Wine desktop slots; Firefox\'s fifth is software-renderer.spec, which skips Firefox off Linux. Before it, the Mac on 2026-11-10/11 (57f28f9f): Chromium 48 and Firefox 48 of 48 or 49 run; on 2026-11-09 (177e242a, under swap) Chromium 44, Firefox 46 and Playwright\'s WebKit 35 of 49 (Git history of this file). Linux on 2026-11-10 (2ee6821c, headless): Chromium 53 of 53 and Firefox 53 of 53, the desktop slots there.',
  browsers: {
    chromium: {version: '153.0.8010.12', sim: 'worker', passed: 47, skipped: 4, minutes: 19},
    firefox: {version: '155.0', sim: 'inline', passed: 48, skipped: 5, minutes: 19},
    webkit: {notRun: 'Safari and WebKit left Stage 7 on 2026-11-10 (the user\'s decision); Playwright\'s WebKit ran 35 of 49 on the Mac on 2026-11-09'},
  },
  failures: [
    {test: 'instructor-conversation.spec.mjs:12', chromium: 'spec', firefox: 'pass',
      note: 'spec (Chromium on SwiftShader, 9 of 9 runs; passes on Metal): the spec\'s placement 80 units from the instructor, inside MunitionsTrooperFrob\'s radius of 160, starts the greeting by radius before its use (the original\'s ScriptedPawn.Tick, IM_Radius); the page stalls about 1.1 s as it starts and the right click takes about 1 s to return, so the 1.8 s greeting is over before the reads. On a fast page the step passed without its use playing anything',
      since: 'rewritten: a reader samples the conversations from each step on; step 1 reads the radius greeting, then a use past the 1 s repeat gate and inside the 5 s radius hold-out plays it again. On Linux at the closing commit 2439b054 it passes in the suite (Chromium and Firefox) and 3 of 3 on Chromium drawing with SwiftShader, at full speed and on two cores (CPUQuota 200 %). On the Mac at the closing commit it passes in the suite in Chromium (38.5 s) and Firefox (33.8 s), 2026-11-11 evening'},
    {test: 'lighting.spec.mjs:10', chromium: 'race', firefox: 'pass',
      note: 'race (Chromium on SwiftShader; passes on Metal): after the switch to Inspect and the resize the page answered the first read 5.9 s later, past the 5 s poll',
      since: 'the poll waits 20 s. On Linux at the closing commit 2439b054 it passes in the suite (Chromium and Firefox) and 3 of 3 on Chromium drawing with SwiftShader at full speed (about 32 s), but on SwiftShader on two cores (CPUQuota 200 %) it ran past the test\'s 120 s budget 3 of 3, every step a frame or more late. On the Mac at the closing commit it passes in the suite with the default headless Chromium in 72.8 s, and in Firefox (2026-11-11 evening). A Mac run should give the suite\'s Chromium Metal, as the 7.x validators have there (`--use-angle=metal`), the renderer a player\'s Chrome on macOS draws with'},
  ],
};
for (const [name, run] of Object.entries(SUITE_RUN.browsers)) if (!run.notRun) {
  const failed = SUITE_RUN.failures.filter(f => f[name] !== 'pass');
  if (failed.some(f => !SUITE_CAUSES[f[name]])) throw new Error(`stage7-criteria: a ${name} failure has no cause`);
  if (run.passed + failed.length + (run.skipped ?? 0) !== SUITE_RUN.tests) throw new Error(`stage7-criteria: ${name} counts ${run.passed} + ${failed.length} + ${run.skipped ?? 0} != ${SUITE_RUN.tests}`);
}

/** The suite run as the note's section of that name (`--suite`). */
function suiteMarkdown() {
  const cell = text => String(text ?? '').replaceAll('|', '\\|');
  const names = Object.keys(SUITE_RUN.browsers), ran = names.filter(n => !SUITE_RUN.browsers[n].notRun);
  const lines = [`## The browser suite by browser\n`, `Last run ${SUITE_RUN.date} on ${SUITE_RUN.machine}, ${SUITE_RUN.tests} tests a browser, one worker. ${SUITE_RUN.rerun}\n`];
  for (const n of names) {
    const b = SUITE_RUN.browsers[n];
    if (b.notRun) { lines.push(`- ${n}: not run. ${b.notRun}.`); continue; }
    const count = {};
    for (const f of SUITE_RUN.failures) if (f[n] !== 'pass') count[f[n]] = (count[f[n]] ?? 0) + 1;
    const causes = Object.entries(count).map(([c, k]) => `${k} ${c}`).join(', ');
    lines.push(`- ${n} ${b.version} (${b.sim} mode): ${b.passed} pass, ${SUITE_RUN.tests - b.passed - (b.skipped ?? 0)} fail${causes ? ` (${causes})` : ''}${b.skipped ? `, ${b.skipped} skipped` : ''}, ${b.minutes} min.`);
  }
  lines.push('', `Causes: ${Object.entries(SUITE_CAUSES).map(([c, text]) => `**${c}**, ${text}`).join('; ')}. A test not listed passed in every browser that ran, but for the skipped ones.`, '');
  lines.push(`| Test | ${ran.join(' | ')} | Why |`, `| --- | ${ran.map(() => '---').join(' | ')} | --- |`);
  for (const f of SUITE_RUN.failures) lines.push(`| ${f.test} | ${ran.map(n => f[n]).join(' | ')} | ${cell(f.note)}${f.fixed ? `. **Fixed:** ${cell(f.fixed)}` : ''}${f.since ? `. **Changed since, not rerun there:** ${cell(f.since)}` : ''} |`);
  return lines.join('\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const counts = {};
  for (const row of CRITERIA) (counts[row.clause] ??= {})[row.status] = (counts[row.clause][row.status] ?? 0) + 1;
  console.log(`| Clause | ${STATUSES.join(' | ')} |\n| --- | ${STATUSES.map(() => '---:').join(' | ')} |`);
  const total = {};
  for (const [c, name] of Object.entries(CLAUSES)) {
    const k = counts[c] ?? {};
    for (const s of STATUSES) total[s] = (total[s] ?? 0) + (k[s] ?? 0);
    console.log(`| 7.${c} ${name} | ${STATUSES.map(s => k[s] ?? 0).join(' | ')} |`);
  }
  console.log(`| **Total** | ${STATUSES.map(s => total[s]).join(' | ')} |`);
  if (process.argv.includes('--list')) for (const row of CRITERIA) console.log(`${row.id}\t${row.status}\t${row.claim}`);
  if (process.argv.includes('--suite')) console.log(`\n${suiteMarkdown()}`);
  // --markdown: the row tables of docs/stage-7-exit-criteria.md, one per clause
  if (process.argv.includes('--markdown')) for (const [c, name] of Object.entries(CLAUSES)) {
    const cell = text => String(text ?? '').replaceAll('|', '\\|');
    const decisions = [...new Set(CRITERIA.filter(row => row.clause === Number(c)).map(row => row.decision).filter(Boolean))];
    console.log(`\n### 7.${c} ${name}${decisions.length ? ` (${decisions.join(', ')})` : ''}\n\n| Row | Criterion | Kind | Proof | Machine | Needed / weak | Status |\n| --- | --- | --- | --- | --- | --- | --- |`);
    for (const row of CRITERIA.filter(row => row.clause === Number(c)))
      console.log(`| ${row.id} | ${cell(row.claim)} | ${row.kind} | ${cell(row.proof.join(', ') || '-')} | ${cell(row.machine)} | ${cell([row.accepted && `accepted: ${row.accepted}`, row.need && `needed: ${row.need}`, row.weak && (row.status === 'FAIL' ? row.weak : `weak: ${row.weak}`), row.excluded].filter(Boolean).join('; ') || '-')} | ${row.status} |`);
  }
}
